pub mod conversion;
pub mod text;
pub mod validation;

pub use conversion::{punycode_decode, punycode_encode, to_ascii, to_unicode};
pub use text::{count_labels, extract_tld, normalize, to_lower};
pub use validation::{is_ascii_domain, is_idn_domain, is_valid_domain, is_valid_label};

use super::text::to_lower;

const PUNYCODE_PREFIX: &str = "xn--";

pub fn to_ascii(domain: &str) -> String {
    let mut result = String::with_capacity(PUNYCODE_PREFIX.len() + domain.len());
    result.push_str(PUNYCODE_PREFIX);
    result.push_str(&to_lower(domain));
    result
}

pub fn to_unicode(domain: &str) -> String {
    strip_punycode_prefix(domain).to_owned()
}

pub fn punycode_encode(domain: &str) -> String {
    let mut result = String::with_capacity(PUNYCODE_PREFIX.len() + domain.len());
    result.push_str(PUNYCODE_PREFIX);
    result.push_str(domain);
    result
}

pub fn punycode_decode(domain: &str) -> String {
    strip_punycode_prefix(domain).to_owned()
}

fn strip_punycode_prefix(domain: &str) -> &str {
    domain.strip_prefix(PUNYCODE_PREFIX).unwrap_or(domain)
}

pub fn to_lower(text: &str) -> String {
    text.bytes()
        .map(|byte| byte.to_ascii_lowercase())
        .map(char::from)
        .collect()
}

pub fn normalize(domain: &str) -> String {
    to_lower(domain)
}

pub fn extract_tld(domain: &str) -> &str {
    match domain.rfind('.') {
        Some(index) => &domain[index + 1..],
        None => domain,
    }
}

pub fn count_labels(domain: &str) -> i32 {
    domain.bytes().filter(|&byte| byte == b'.').count() as i32 + 1
}

pub fn is_valid_domain(domain: &str) -> bool {
    !domain.is_empty() && domain.len() <= 255
}

pub fn is_valid_label(label: &str) -> bool {
    !label.is_empty() && label.len() <= 63
}

pub fn is_ascii_domain(domain: &str) -> bool {
    domain.is_ascii()
}

pub fn is_idn_domain(domain: &str) -> bool {
    !is_ascii_domain(domain)
}

mod idna;

use std::env;

fn main() {
    let domain = env::args()
        .nth(1)
        .unwrap_or_else(|| "multi.level.domain.name.test".to_owned());

    let result1 = idna::to_ascii(&domain);
    let result2 = idna::to_unicode(&result1);
    let result3 = idna::punycode_encode(&domain);
    let result4 = idna::punycode_decode(&result3);
    let result5 = idna::is_valid_domain(&domain);
    let result6 = idna::is_valid_label("testlabel");
    let result7 = idna::is_ascii_domain(&domain);
    let result8 = idna::is_idn_domain(&domain);
    let result9 = idna::to_lower("MIXEDCase");
    let result10 = idna::normalize(&domain);
    let result11 = idna::extract_tld(&domain);
    let result12 = idna::count_labels(&domain);

    println!("{}", result1);
    println!("{}", result2);
    println!("{}", result3);
    println!("{}", result4);
    println!("{}", result5 as u8);
    println!("{}", result6 as u8);
    println!("{}", result7 as u8);
    println!("{}", result8 as u8);
    println!("{}", result9);
    println!("{}", result10);
    println!("{}", result11);
    println!("{}", result12);
}

